\title[The sieve's advantage is the survivor filter]{The Sieve's Advantage Is the Survivor Filter:\\ Exact Thresholds, Hensel Lines, and the Quadratic-Residue\\ Restriction of the Relation Pool in a Toy Quadratic Sieve}
\author{Aristotle}
\date{2026-10-05}

\begin{document}

\begin{abstract}
We measure and analyze the relation-collection phase of a toy quadratic sieve for semiprimes $N$ up to $2^{32}$. We ask two questions. (H1) Is the sieve's advantage over naive trial division a constant factor coming from filtering survivors, or does it grow with scale? (H2) Is the relation yield predicted by the random-integer model $0.90\,\rho(u)$? H1 is confirmed. The measured advantage lies between $13.68\times$ and $20.51\times$ across six settings, and its ratio to the factor-base size is flat at $0.12$--$0.22$. H2 is refuted: the model overpredicts yield by about $1.55\times$ at median $u\approx 3$. We support both findings with exact theorems. (i) The log-sieve threshold accepts $v$ if and only if $v$ is smooth over the factor base with every exponent at most the sieve height $K$. Hence a sieve using first powers only accepts exactly the squarefree smooth values, and a sieve with $K\ge\log_2 v$ agrees with trial division. (ii) For an odd prime $p\nmid N$, $x^2\equiv N\pmod{p^k}$ has exactly two solutions for all $k\ge1$ if $\leg{N}{p}=+1$ and none if $\leg Np=-1$. (iii) The total sieve work over $M$ values is at most $\sum_p\sum_{k\le K}2(M/p^k+1)$. (iv) Restricting to quadratic-residue primes, read as an effective bound $B/2$, multiplies $u$ exactly by $\ln B/(\ln B-\ln 2)>1$, which explains the direction of the H2 deviation (cross-setting correlation $0.72$). (v) A unit square modulo $pq$ has exactly four square roots, exactly two of them non-trivial. We give a complete certificate factoring $N=103\,764\,863=9127\times 11369$ from four relations, each of which has a repeated prime factor.
\end{abstract}

\maketitle

\section{Introduction}

The quadratic sieve factors an odd composite $N$ in two phases. It first collects \emph{relations}, integers $x$ near $\sqrt N$ for which $Q(x)=x^2-N$ is $B$-smooth. It then finds, by linear algebra over $\F_2$, a subset of relations whose product is a square, and extracts a factor of $N$ from the resulting congruence of squares.

Two standard claims about relation collection are usually stated without much measurement: that sieving is much faster than trial division, and that the yield follows Dickman's function $\rho(u)$ with $u=\ln Q(x)/\ln B$. An earlier round of this project fitted $0.90\,\rho(u)$ for $u\in[2,3]$, $v\le 2^{23}$, and left open how large the sieve's algorithmic advantage actually is. Here we close that question and test the yield model at larger scale.

\begin{itemize}
\item \textbf{H1 (confirmed).} The advantage $A_{\mathrm{total}}$ is the constant survivor-filtering factor: $13.68$--$20.51\times$ across six settings ($N\le 2^{32}$), with $A/\pi_{\mathrm{FB}}$ flat at $0.12$--$0.22$ and no growth with scale. Per value, about $100$ divisions are replaced by about $2$ log additions, plus division of survivors only.
\item \textbf{H2 (refuted, refining the earlier model).} The model $0.90\,\rho(u)$ overpredicts yield about $1.55\times$ at $u_{\mathrm{med}}\approx3$, with $0/6$ settings in band. A prime $p$ divides $x^2-N$ only if $\leg Np=+1$. Read as an effective bound, this raises $u$ by $\ln B/(\ln B-\ln2)$ and predicts yield ratios $0.44$--$0.52$. We observed $0.54$--$0.76$, with correlation $0.72$.
\end{itemize}

\subsection*{Notation}
$N>1$ is odd and not a square, and $Q(x)=x^2-N$. For a prime $p$, $v_p(\cdot)$ is the $p$-adic valuation. $\leg Np$ is the Legendre symbol, and $\pi(B)$ is the number of primes up to $B$. A positive integer is \emph{$S$-smooth} if all its prime factors lie in $S$, and \emph{$B$-smooth} if $S=\{p\le B\}$. Dickman's $\rho$ satisfies $\rho(u)=1$ on $[0,1]$ and $u\rho'(u)=-\rho(u-1)$ for $u>1$.

\section{The log sieve and its exact acceptance criterion}

\begin{definition}
Let $S$ be a finite set of primes and $K\ge1$. For a positive integer $v$ put
\[
h_K(v,p)=\#\{1\le k\le K:\ p^k\mid v\},\qquad
P_{S,K}(v)=\prod_{p\in S}p^{h_K(v,p)},\qquad
L_{S,K}(v)=\sum_{p\in S}h_K(v,p)\log p .
\]
The value $v$ \emph{survives} the sieve of height $K$ if $L_{S,K}(v)=\log v$.
\end{definition}

\begin{lemma}\label{lem:min}
For a prime $p$ and $v\neq0$, $h_K(v,p)=\min(v_p(v),K)$.
\end{lemma}
\begin{proof}
$p^k\mid v$ if and only if $k\le v_p(v)$.
\end{proof}

\begin{lemma}\label{lem:div}
$L_{S,K}(v)=\log P_{S,K}(v)$ and $P_{S,K}(v)\mid v$. In particular $L_{S,K}(v)\le\log v$.
\end{lemma}
\begin{proof}
Take logarithms of the product. By Lemma~\ref{lem:min} the exponents of $P_{S,K}(v)$ are bounded by those of $v$.
\end{proof}

\begin{theorem}[Exact acceptance criterion]\label{thm:accept}
For $v\ge1$: $L_{S,K}(v)=\log v$ if and only if $v$ is $S$-smooth and $v_p(v)\le K$ for every prime $p$.
\end{theorem}
\begin{proof}
Survival is equivalent to $P_{S,K}(v)=v$. Given divisibility, this holds if and only if $\min(v_p(v),K)=v_p(v)$ for $p\in S$ and $v_p(v)=0$ for $p\notin S$.
\end{proof}

\begin{corollary}[The first-power sieve]\label{cor:first}
With $K=1$, $v$ survives if and only if $v$ is $S$-smooth and squarefree. If $v$ is not squarefree, then $L_{S,1}(v)<\log v$.
\end{corollary}

\begin{corollary}[Exactness of the full sieve]\label{cor:full}
If $S=\{p\le B\}$ and $K\ge\log_2 v$, then $v$ survives if and only if $v$ is $B$-smooth.
\end{corollary}
\begin{proof}
$v_p(v)\le\log_2 v\le K$ for every prime $p$.
\end{proof}

\begin{remark}
Corollary~\ref{cor:full} lets us read H1 as a purely algorithmic gain: no relation is lost and no false positive is admitted. Corollary~\ref{cor:first} identifies the main bug in our ledger. Under an exact threshold, a first-power sieve loses precisely the non-squarefree smooth values, which made up $54$--$91\%$ of relations in our settings.
\end{remark}

\section{Sieve lines modulo prime powers}

\begin{lemma}[Hensel step]\label{lem:hstep}
Let $p$ be an odd prime, $k\ge1$, $p^k\mid x^2-N$ and $p\nmid x$. Then there is $y\equiv x\pmod{p^k}$ with $p^{k+1}\mid y^2-N$.
\end{lemma}
\begin{proof}
Write $x^2-N=p^kc$ and $y=x+tp^k$. Then $y^2-N=p^k(c+2xt)+t^2p^{2k}$. Choose $t\equiv -c(2x)^{-1}\pmod p$.
\end{proof}

\begin{theorem}[Hensel lifting]\label{thm:hensel}
If $p$ is an odd prime, $p\nmid N$ and $p\mid x_0^2-N$, then for each $k\ge1$ there is $y\equiv x_0\pmod p$ with $p^k\mid y^2-N$.
\end{theorem}

\begin{lemma}[At most two lines]\label{lem:two}
If $p$ is odd, $p\nmid N$, and $p^k$ divides both $x^2-N$ and $y^2-N$, then $p^k\mid x-y$ or $p^k\mid x+y$.
\end{lemma}
\begin{proof}
$p^k\mid(x-y)(x+y)$. The prime $p$ cannot divide both factors, since then $p\mid 2x$, so $p\mid x$, so $p\mid N$.
\end{proof}

\begin{theorem}[Exactly two lines, or none]\label{thm:lines}
Let $p$ be an odd prime, $p\nmid N$, $k\ge1$, and let $r(p^k)$ be the number of residues $x\bmod p^k$ with $x^2\equiv N$. Then $r(p^k)=2$ if $\leg Np=+1$, and $r(p^k)=0$ if $\leg Np=-1$.
\end{theorem}
\begin{proof}
Lift a root using Theorem~\ref{thm:hensel}. Its negative is a distinct root because $p\nmid 2y$, and by Lemma~\ref{lem:two} there are no others. A non-residue has no root modulo $p$, hence none modulo $p^k$.
\end{proof}

\begin{proposition}[The $2$-adic cap]\label{prop:two}
Let $N$ be odd. If $4\mid x^2-N$ then $N\equiv1\pmod4$. If $8\mid x^2-N$ then $N\equiv1\pmod8$.
\end{proposition}
\begin{proof}
Then $x$ is odd, and odd squares are $\equiv1\pmod 8$.
\end{proof}

For $N=103\,764\,863\equiv7\pmod8$, no value $x^2-N$ is divisible by $4$.

\section{The work bound (H1)}

\begin{lemma}\label{lem:window}
For $m\ge1$, a window of $M$ consecutive integers contains at most $\lfloor M/m\rfloor+1$ members of any residue class modulo $m$.
\end{lemma}
\begin{proof}
The map $x\mapsto\lfloor(x-a)/m\rfloor$ is injective on the class and takes values in $\{0,\dots,\lfloor M/m\rfloor\}$.
\end{proof}

\begin{proposition}\label{prop:hits}
For an odd prime $p\nmid N$ and $k\ge0$, at most $2(\lfloor M/p^k\rfloor+1)$ values of $x$ in a window of length $M$ satisfy $p^k\mid x^2-N$.
\end{proposition}

\begin{theorem}[Total sieve work]\label{thm:work}
Let $S$ be a set of odd primes not dividing $N$. Over a window of $M$ consecutive $x$,
\[
\sum_{x}\sum_{p\in S}h_K\bigl(|x^2-N|,p\bigr)\ \le\ \sum_{p\in S}\sum_{k=1}^{K}2\Bigl(\Bigl\lfloor\frac{M}{p^k}\Bigr\rfloor+1\Bigr).
\]
\end{theorem}
\begin{proof}
Exchange the sums and apply Proposition~\ref{prop:hits} for each $k$.
\end{proof}

Per value this is about $2\sum_{p\in S}1/(p-1)=O(\log\log B)$ additions, against about $\pi(B)$ divisions for trial division.

