\section{The relation pool is quadratic-residue restricted (H2)}

\begin{proposition}[Support]\label{prop:support}
If $p$ is an odd prime, $p\nmid N$ and $p\mid x^2-N$, then $\leg Np=+1$. Hence every $B$-smooth $Q(x)$ is smooth over
\[\mathcal P(N,B)=\{2\}\cup\{p\le B\text{ odd}:\ p\mid N\text{ or }\leg Np=+1\}.\]
\end{proposition}

For $N=103\,764\,863$ and $B=60$, $\mathcal P(N,B)=\{2,11,17,19,23,31,37,43,47,59\}$, which is $10$ of the $17$ primes up to $60$.

\begin{proposition}[Effective-$u$ identity]\label{prop:ueff}
For real $B>2$ and $v>1$,
\[\frac{\ln v}{\ln(B/2)}=\frac{\ln v}{\ln B}\cdot\frac{\ln B}{\ln B-\ln2}>\frac{\ln v}{\ln B}.\]
\end{proposition}
\begin{proof}
$\ln(B/2)=\ln B-\ln2\in(0,\ln B)$.
\end{proof}

Treating the restricted pool as though the bound were $B/2$, which is a heuristic that ignores the doubled hit rate of Theorem~\ref{thm:lines}, predicts a yield ratio $\rho(u_{\mathrm{eff}})/\rho(u)$ with $u_{\mathrm{eff}}=u\ln B/(\ln B-\ln2)$.

