"""Exhaustive check of the CRT coin flip and the Hensel line count for small moduli."""
from __future__ import annotations
import math
from typing import List


def odd_primes(n: int) -> List[int]:
    return [p for p in range(3, n + 1) if all(p % d for d in range(2, math.isqrt(p) + 1))]


def roots_of_square(y: int, n: int) -> List[int]:
    s = y * y % n
    return [x for x in range(n) if x * x % n == s]


def main() -> None:
    ps = odd_primes(40)
    checked = 0
    for i, p in enumerate(ps):
        for q in ps[i + 1:]:
            n = p * q
            for y in range(1, n):
                if math.gcd(y, n) != 1:
                    continue
                rs = roots_of_square(y, n)
                useful = [x for x in rs if x not in (y, (n - y) % n)]
                assert len(rs) == 4 and len(useful) == 2
                for x in useful:
                    g = math.gcd(x - y, n)
                    assert g in (p, q)
                checked += 1
    print(f"CRT coin flip: verified 4 roots / 2 useful for {checked} unit squares "
          f"over all pairs of distinct odd primes below 40")
    # Hensel: exactly 2 or 0 roots modulo p^k
    cases = 0
    for p in odd_primes(30):
        for N in range(1, 200):
            if N % p == 0:
                continue
            res = pow(N, (p - 1) // 2, p) == 1
            for k in (1, 2, 3):
                m = p ** k
                c = sum(1 for x in range(m) if (x * x - N) % m == 0)
                assert c == (2 if res else 0)
                cases += 1
    print(f"Hensel lines: verified r(p^k) in {{0, 2}} matching (N|p) in {cases} cases")


if __name__ == "__main__":
    main()
